1	package agentusageview
2	
3	import (
4		"errors"
5		"log"
6		"os"
7	
8		"github.com/charmbracelet/bubbles/spinner"
9		tea "github.com/charmbracelet/bubbletea"
10	
11		"github.com/anthnel/devdesk/internal/agentusage"
12		sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
13		"github.com/anthnel/devdesk/internal/ui/theme"
14	)
15	
16	// Update handles messages.
17	func (m Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
18		switch msg := msg.(type) {
19		case tea.WindowSizeMsg:
20			return m.handleResize(msg)
21		case sessionListLoadedMsg:
22			return m.handleListLoaded(msg)
23		case usageDeltaMsg:
24			return m.handleUsageDelta(msg)
25		case usagePollTickMsg:
26			return m.handlePollTick(msg)
27		case spinner.TickMsg:
28			return m.handleSpinnerTick(msg)
29		case tea.KeyMsg:
30			return m.handleKey(msg)
31		}
32		m.footer.Handle(msg)
33		return m, nil
34	}
35	
36	// handleResize sizes both tables, so going back from the agents level finds the
37	// sessions table already fitted. The full viewport width, borders included
38	// (Rule 116).
39	func (m Model) handleResize(msg tea.WindowSizeMsg) (tea.Model, tea.Cmd) {
40		m.width, m.height = msg.Width, max(msg.Height-1, 1)
41		m.table.Resize(m.width, m.height)
42		m.agentTable.Resize(m.width, m.height)
43		return m, nil
44	}
45	
46	// handleListLoaded takes a listing, or ignores one from a superseded read.
47	// A failed read keeps the rows already shown: they are dated, not wrong.
48	func (m Model) handleListLoaded(msg sessionListLoadedMsg) (tea.Model, tea.Cmd) {
49		if msg.gen != m.gen {
50			return m, nil
51		}
52		m.loading = false
53		if msg.err != nil {
54			// The error can name a path; it is logged, never shown (Rule 128).
55			log.Printf("ERROR [agentusageview] list sessions: %v", msg.err)
56			m.loadErr = true
57			return m, nil
58		}
59		m.loadErr = false
60		m.root = msg.root
61		m.omitted = msg.listing.Omitted
62		m.table.SetItems(rowsOf(msg))
63		return m, nil
64	}
65	
66	// rowsOf folds each project once, so no Cell does it per frame.
67	func rowsOf(msg sessionListLoadedMsg) []sessionRow {
68		rows := make([]sessionRow, len(msg.listing.Sessions))
69		for i, s := range msg.listing.Sessions {
70			project := noProject
71			if s.Project != "" {
72				project = theme.FoldHome(s.Project)
73			}
74			rows[i] = sessionRow{Session: s, project: project}
75		}
76		return rows
77	}
78	
79	// handleSpinnerTick advances the spinner only while a read or a parse is in
80	// flight, so the chain ends with the load.
81	func (m Model) handleSpinnerTick(msg spinner.TickMsg) (tea.Model, tea.Cmd) {
82		if !m.loading && !m.agentsLoading {
83			return m, nil
84		}
85		var cmd tea.Cmd
86		m.spinner, cmd = m.spinner.Update(msg)
87		m.footer.SetSpinnerFrame(m.spinner.View())
88		return m, cmd
89	}
90	
91	// handleUsageDelta takes the answer to the read in flight, or drops one that
92	// is for another generation or that nobody is waiting for. A failed read keeps
93	// the rows already shown.
94	func (m Model) handleUsageDelta(msg usageDeltaMsg) (tea.Model, tea.Cmd) {
95		if msg.gen != m.agentGen || m.level != levelAgents || !m.reading || m.agg == nil {
96			return m, nil
97		}
98		m.reading = false
99		if msg.err != nil {
100			return m.failRead(msg.err)
101		}
102		if err := m.agg.Apply(msg.delta); err != nil {
103			// Not read from the current cursor: read again from where it is now.
104			log.Printf("ERROR [agentusageview] apply delta: %v", err)
105			m.reading = true
106			return m, readDeltaCmd(m.agentGen, m.agg.Cursor())
107		}
108		m.agentsErr = false
109		if msg.delta.Full() || !msg.delta.Empty() {
110			m = m.withUsage(m.agg.Usage(), msg.delta.Full())
111		}
112		if m.fullPending {
113			m.fullPending = false
114			return m, m.startRead(true)
115		}
116		m.agentsLoading = false
117		if m.agg.Activity().Settled(msg.at, quietPeriod) {
118			m.pollStopped = true
119			return m, nil // nothing left to wait for: the chain ends here
120		}
121		return m, pollTickCmd(m.agentGen)
122	}
123	
124	// failRead records a failed read. Only the first failure of a streak is
125	// logged. The error names files by base name only; it never reaches the UI.
126	// A deleted transcript ends the poll chain; any other failure retries, after
127	// the full read a ctrl+r left pending, if there is one.
128	func (m Model) failRead(err error) (tea.Model, tea.Cmd) {
129		if !m.agentsErr {
130			log.Printf("ERROR [agentusageview] read session: %v", err)
131		}
132		m.agentsErr = true
133		if errors.Is(err, os.ErrNotExist) {
134			m.agentsLoading, m.fullPending, m.pollStopped = false, false, true
135			return m, nil
136		}
137		if m.fullPending {
138			m.fullPending = false
139			return m, m.startRead(true)
140		}
141		m.agentsLoading = false
142		return m, pollTickCmd(m.agentGen)
143	}
144	
145	// handlePollTick starts the incremental read a tick asks for, unless the tick
146	// belongs to a superseded chain or a read is already in flight. No spinner:
147	// polling is silent.
148	func (m Model) handlePollTick(msg usagePollTickMsg) (tea.Model, tea.Cmd) {
149		if msg.gen != m.agentGen || m.level != levelAgents || m.agg == nil || m.reading || m.pollStopped {
150			return m, nil
151		}
152		return m, m.startRead(false)
153	}
154	
155	// startRead marks a read in flight and returns it; full reads everything again.
156	func (m *Model) startRead(full bool) tea.Cmd {
157		c := m.agg.Cursor()
158		if full {
159			c = c.Rewound()
160			m.agentsLoading, m.pollStopped = true, false
161		}
162		m.reading = true
163		return readDeltaCmd(m.agentGen, c)
164	}
165	
166	// handleKey gives the filter the keyboard first; ctrl+r refreshes the level on
167	// screen, → and enter open a session, ← and esc go back.
168	func (m Model) handleKey(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
169		if m.InEditMode() {
170			return m, m.activeTable(msg)
171		}
172		key := msg.String()
173		if key == "ctrl+r" {
174			return m.refresh()
175		}
176		a := m.availability()
177		switch key {
178		case "right", "enter":
179			return m.guard(a.Open, m.openSelected)
180		case "left", "esc":
181			// Silent at the top level: a stray esc is not worth a footer line.
182			if a.Close.Enabled() {
183				return m.closeAgents()
184			}
185		case ".":
186			if m.level == levelAgents {
187				return m.cycleAgentSort(msg)
188			}
189		}
190		return m, m.activeTable(msg)
191	}
192	
193	// agentsTree reports whether the agents table shows the tree: no sort active.
194	func (m Model) agentsTree() bool {
195		column, _ := m.agentTable.SortState()
196		return column < 0
197	}
198	
199	// cycleAgentSort hands `.` to the agents table, then rebuilds the rows so the
200	// branches follow the new order: a sorted list is flat, a branch there would
201	// lie about who is whose child.
202	func (m Model) cycleAgentSort(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
203		selected, hadSelection := m.selectedAgentKey()
204		cmd := m.agentTable.Update(msg)
205		m.agentTable.SetItems(agentRows(m.usage, m.agentsTree()))
206		m.agentTable.Remeasure() // the Agent column narrows or widens by the branch
207		if hadSelection {
208			m.selectAgentKey(selected)
209		}
210		return m, cmd
211	}
212	
213	// activeTable hands a key to the table of the level on screen.
214	func (m *Model) activeTable(msg tea.KeyMsg) tea.Cmd {
215		if m.level == levelAgents {
216			return m.agentTable.Update(msg)
217		}
218		return m.table.Update(msg)
219	}
220	
221	// openSelected opens the selected session's agents. The table stays empty,
222	// headers included, until the parse answers (Rule 139).
223	func (m Model) openSelected() (tea.Model, tea.Cmd) {
224		row, _ := m.table.Selected() // availability checked a row exists
225		m.usage = agentusage.Usage{}
226		m.level = levelAgents
227		m.open = row.Session
228		m.agentGen++
229		m.agg = agentusage.NewAggregate(row.Parent)
230		m.fullPending, m.agentsErr = false, false
231		m.agentTable.FilterBar().ClearSearch() // a filter typed for another session
232		m.agentTable.SetItems(nil)
233		return m, tea.Batch(m.startRead(true), m.spinner.Tick)
234	}
235	
236	// closeAgents returns to the sessions, cursor and filter as they were. Bumping
237	// agentGen drops a parse still in flight.
238	func (m Model) closeAgents() (tea.Model, tea.Cmd) {
239		m.level = levelSessions
240		m.agentGen++
241		m.agentsLoading, m.agentsErr = false, false
242		m.agg, m.reading, m.fullPending = nil, false, false
243		m.usage = agentusage.Usage{}
244		m.agentTable.SetItems(nil)
245		return m, nil
246	}
247	
248	// refresh starts a new read of the level on screen under a new generation.
249	// The rows stay on screen.
250	func (m Model) refresh() (tea.Model, tea.Cmd) {
251		if m.level == levelAgents {
252			return m.refreshAgents()
253		}
254		m.gen++
255		m.loading = true
256		m.loadErr = false
257		return m, tea.Batch(listSessionsCmd(m.gen), m.spinner.Tick)
258	}
259	
260	// refreshAgents reads the open session from the start. A read already in
261	// flight is never doubled (one per Aggregate): the full read follows its answer.
262	func (m Model) refreshAgents() (tea.Model, tea.Cmd) {
263		if m.agg == nil {
264			m.agg = agentusage.NewAggregate(m.open.Parent)
265		}
266		if m.reading {
267			spin := !m.agentsLoading // a spinner chain already runs otherwise
268			m.fullPending, m.agentsLoading = true, true
269			if spin {
270				return m, m.spinner.Tick
271			}
272			return m, nil
273		}
274		m.agentGen++
275		return m, tea.Batch(m.startRead(true), m.spinner.Tick)
276	}
277	
278	// InEditMode tells the router the filter has the keyboard.
279	func (m Model) InEditMode() bool { return m.activeFilterBar().InEditMode() }
280	
281	// FilterBarVisible closes the viewport rectangle around the bar.
282	func (m Model) FilterBarVisible() bool { return m.activeFilterBar().IsVisible() }
283	
284	// activeFilterBar is the bar of the level on screen; each level has its own.
285	func (m Model) activeFilterBar() *sharedcomponents.FilterBar {
286		if m.level == levelAgents {
287			return m.agentTable.FilterBar()
288		}
289		return m.table.FilterBar()
290	}
