3	import (
4		"fmt"
5		"sync"
6		"time"
7	
8		tea "github.com/charmbracelet/bubbletea"
9	
10		"github.com/anthnel/devdesk/internal/agentusage"
11	)
12	
13	// listSessionsCmd resolves the projects root and lists it, all inside the Cmd:
14	// the model is not touched (Rule 110) and the answer carries gen back.
15	func listSessionsCmd(gen int) tea.Cmd {
16		return func() tea.Msg {
17			root, err := agentusage.ProjectsRoot()
18			if err != nil {
19				return sessionListLoadedMsg{gen: gen, err: err}
20			}
21			listing, err := agentusage.ListSessions(root)
22			return sessionListLoadedMsg{gen: gen, root: root, listing: listing, err: err}
23		}
24	}
25	
26	// pollInterval is the pause between two reads of the open session; a variable
27	// so tests can shorten it. quietPeriod is how long a session must be quiet to
28	// be considered settled and no longer polled.
29	var (
30		pollInterval = 2 * time.Second
31		quietPeriod  = 5 * time.Minute
32	)
33	
34	// now is the clock the poll chain reads, replaceable in tests.
35	var now = time.Now
36	
37	// usageDeltaMsg carries one incremental read. gen is agentGen at the time the
38	// read started; at is when it finished.
39	type usageDeltaMsg struct {
40		gen   int
41		delta agentusage.Delta
42		err   error
43		at    time.Time
44	}
45	
46	// String and GoString keep the delta's paths out of any formatted dump: fmt
47	// cannot call the Delta's own redacting methods through an unexported field.
48	func (m usageDeltaMsg) String() string {
49		return fmt.Sprintf("usageDeltaMsg{gen: %d, delta: %v, failed: %t}", m.gen, m.delta, m.err != nil)
50	}
51	
52	// GoString is String.
53	func (m usageDeltaMsg) GoString() string { return m.String() }
54	
55	// usagePollTickMsg says the poll interval of generation gen has elapsed.
56	type usagePollTickMsg struct{ gen int }
57	
58	// agentsResumeMsg asks Update to restart a poll chain that stopped.
59	type agentsResumeMsg struct{}
60	
61	// readDeltaCmd reads what changed since c. It owns its Cursor copy and touches
62	// no model (Rule 110); the answer carries gen and the time of the read.
63	func readDeltaCmd(gen int, c agentusage.Cursor) tea.Cmd {
64		return func() tea.Msg {
65			delta, err := agentusage.ReadDelta(c)
66			return usageDeltaMsg{gen: gen, delta: delta, err: err, at: now()}
67		}
68	}
69	
70	// pollTickCmd waits pollInterval, then answers with a tick of generation gen.
71	// The interval is read when the Cmd is built (Update's goroutine), never from
72	// the Cmd's own. The Cmd may be run twice (a caller inspecting it, then
73	// running it): the wait happens once and the answer is kept.
74	func pollTickCmd(gen int) tea.Cmd {
75		d := pollInterval
76		var once sync.Once
77		return func() tea.Msg {
78			once.Do(func() { time.Sleep(d) })
79			return usagePollTickMsg{gen: gen}
80		}
81	}
82	
83	// resumeCmd answers agentsResumeMsg at once.
84	func resumeCmd() tea.Cmd {
85		return func() tea.Msg { return agentsResumeMsg{} }
86	}
