159	// driver runs Cmds the way Bubble Tea does (concurrently) and feeds the poll
160	// messages back to Update on the test goroutine. Other messages (spinner ticks)
161	// are dropped, so no unrelated chain keeps it busy.
162	type driver struct {
163		t       *testing.T
164		m       Model
165		ch      chan tea.Msg
166		pending int
167		reads   int // usageDeltaMsg delivered
168	}
169	
170	func newDriver(t *testing.T, m Model, cmd tea.Cmd) *driver {
171		d := &driver{t: t, m: m, ch: make(chan tea.Msg, 256)}
172		d.run(cmd)
173		return d
174	}
175	
176	func (d *driver) run(cmd tea.Cmd) {
177		if cmd == nil {
178			return
179		}
180		d.pending++
181		go func() { d.ch <- cmd() }()
182	}
183	
184	// until pumps messages until done(model) holds (true), nothing is pending any
185	// more (false), or the deadline passes (false).
186	func (d *driver) until(done func(Model) bool, deadline time.Duration) bool {
187		d.t.Helper()
188		limit := time.After(deadline)
189		for {
190			if done(d.m) {
191				return true
192			}
193			if d.pending == 0 {
194				return false
195			}
196			select {
197			case msg := <-d.ch:
198				d.pending--
199				d.deliver(msg)
200			case <-limit:
201				return false
202			}
203		}
204	}
205	
206	func (d *driver) deliver(msg tea.Msg) {
207		switch v := msg.(type) {
208		case tea.BatchMsg:
209			for _, c := range v {
210				d.run(c)
211			}
212		case usageDeltaMsg:
213			d.reads++
214			d.feed(v)
215		case usagePollTickMsg:
216			d.feed(v)
217		}
218	}
219	
220	func (d *driver) feed(msg tea.Msg) {
221		updated, cmd := d.m.Update(msg)
222		d.m = updated.(Model)
223		d.run(cmd)
224	}
